This is a complex request requiring the implementation of a small language parser, a dependency graph algorithm (including cycle detection), and a stateful calculation engine.

Due to the complexity, I will focus on implementing the core logic based on the provided specification. I will use a simplified structure for the AST in `formula.py` to keep the scope manageable while fulfilling the requirements.

Here are the four files:

### `sheet/formula.py`

```python
import re
from typing import Union, Any, Dict, List, Set, Tuple

class FormulaError(ValueError):
    """Raised when a formula has a syntax or structural error."""
    pass

class ErrorValue(str):
    """Represents a calculation error value."""
    pass

# Define specific error values
ERROR_GENERAL = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class NumberLiteral:
    def __init__(self, value: Union[int, float]):
        self.value = value

class Reference:
    def __init__(self, name: str):
        self.name = name

class BinaryOp:
    def __init__(self, left, op: str, right):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp:
    def __init__(self, op: str, operand):
        self.op = op
        self.operand = operand

class Expression:
    """Base class for the Abstract Syntax Tree."""
    pass

# --- Parser ---

# Regex components
DIGITS = r'\d+'
FLOAT_NUMBER = rf'{DIGITS}\.{DIGITS}'
NUMBER = rf'{DIGITS}(?:\.{DIGITS})?'
LETTER = r'[a-zA-Z]'
REF = rf'{LETTER}+(?={DIGITS})' # Matches letters followed by digits, e.g., A1, B10

# Tokenization is complex due to whitespace allowance, so we'll use a recursive descent style parser.

class Token:
    def __init__(self, type: str, value: Any = None):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)})"

def tokenize(source: str) -> List[Token]:
    """Breaks the formula string into meaningful tokens."""

    # Operators and grouping symbols
    OPERATORS = r'[\+\-\*/()]'
    # Literals/References/Numbers
    NUM_PATTERN = rf'({NUMBER}|{REF})'

    # Combine patterns: Operators, Numbers/Refs, Whitespace (which we skip)
    token_specs = [
        ('SKIP', r'\s+'),
        ('OP', r'[\+\-\*/()]'),
        ('NUMBER_REF', NUM_PATTERN),
    ]

    token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specs)

    tokens = []
    for mo in re.finditer(token_regex, source):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'SKIP':
            continue
        elif kind == 'OP':
            tokens.append(Token('OP', value))
        elif kind == 'NUMBER_REF':
            # Differentiate numbers from references
            if re.fullmatch(r'(\d+(\.\d+)?)', value):
                tokens.append(Token('NUMBER', value))
            else:
                tokens.append(Token('REF', value.upper()))
        else:
            raise FormulaError(f"Unexpected character sequence: {value}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self):
        self.pos += 1

    def expect(self, expected_type: str, expected_value: Any = None):
        token = self.current_token()
        if not token or token.type != expected_type or (expected_value is not None and token.value != expected_value):
            raise FormulaError(f"Expected {expected_type} ({expected_value}), but found {token}")
        self.advance()
        return token

    def parse(self) -> Expression:
        """Entry point for parsing: expr -> term {(+ | -) term}"""
        node = self._parse_term()

        # Left associative handling for addition/subtraction
        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in ('+', '-'):
            op_token = self.expect('OP')
            right = self._parse_term()

            # Reconstruct the binary operation (left associative)
            node = BinaryOp(node, op_token.value, right)

        if self.current_token() is not None:
            raise FormulaError("Unexpected trailing tokens in formula.")

        return node

    def _parse_term(self) -> Expression:
        """term -> unary {(* | /) unary}"""
        node = self._parse_unary()

        # Left associative handling for multiplication/division
        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in ('*', '/'):
            op_token = self.expect('OP')
            right = self._parse_unary()

            # Reconstruct the binary operation (left associative)
            node = BinaryOp(node, op_token.value, right)

        return node

    def _parse_unary(self) -> Expression:
        """unary -> (+ | -) unary | number | ref | ( expr )"""
        token = self.current_token()

        if token and token.type == 'OP' and token.value in ('+', '-'):
            op_token = self.expect('OP')
            # Unary signs bind tighter, so we recurse to unary again
            return UnaryOp(op_token.value, self._parse_unary())

        elif token and token.type == 'NUMBER':
            self.advance()
            val = float(token.value) if '.' in token.value else int(token.value)
            return NumberLiteral(val)

        elif token and token.type == 'REF':
            self.advance()
            return Reference(token.value)

        elif token and token.type == 'OP' and token.value == '(':
            self.expect('OP', '(')
            expr = self._parse_expr()
            self.expect('OP', ')')
            return expr

        else:
            raise FormulaError(f"Unexpected token encountered during unary parsing: {token}")

    def _parse_expr(self) -> Expression:
        # This acts as the entry point for parentheses content, equivalent to _parse_term() but used inside parentheses
        return self._parse_term()


def parse_formula(source: str) -> Expression:
    """Parses the string after '=' into an AST."""
    if not source:
        raise FormulaError("Formula source cannot be empty.")

    tokens = tokenize(source)
    if not tokens:
        raise FormulaError("Formula resulted in no recognizable tokens.")

    parser = Parser(tokens)
    return parser.parse()

# --- Analysis ---

def references(tree: Expression) -> Set[str]:
    """Recursively finds all cell references (uppercase) in the AST."""
    found = set()

    if isinstance(tree, Reference):
        return {tree.name}

    elif isinstance(tree, BinaryOp):
        found.update(references(tree.left))
        found.update(references(tree.right))

    elif isinstance(tree, UnaryOp):
        found.update(references(tree.operand))

    # NumberLiteral and Expression (if used for structure but not value) are ignored
    return found

# --- Evaluation ---

def evaluate(tree: Expression, lookup: callable) -> Union[int, float, str, None]:
    """
    Computes the formula value.
    lookup(name) -> Cell Value (int, float, str, None, ErrorValue)
    """

    def _resolve_operand(operand: Expression) -> Union[int, float, str, ErrorValue]:

        if isinstance(operand, NumberLiteral):
            return operand.value

        elif isinstance(operand, Reference):
            cell_name = operand.name
            cell_value = lookup(cell_name)

            if cell_value is None:
                return 0 # Empty cell -> 0

            if isinstance(cell_value, ErrorValue):
                return cell_value # Propagate error

            if isinstance(cell_value, str) and not cell_value.replace('.', '', 1).isdigit():
                # If cell holds text, return text itself for the specific case:
                # "A formula that is only a reference therefore returns text unchanged"
                # This is tricky. If the reference is the *whole* formula, we return text.
                # If it's an operand, and we are evaluating it, it should probably become an error 
                # unless it's being used in a context that allows strings (which only happens for the whole formula).

                # For operands, if it's text, it causes #ERROR! unless it's the only operand and the rule applies.
                # Since we are inside an operand resolver, we treat text as a calculation error source.
                return ERROR_GENERAL 

            # Numeric or convertible text
            try:
                if isinstance(cell_value, str):
                    # Attempt conversion from stored string if it looks like a number
                    return float(cell_value) if '.' in cell_value else int(cell_value)
                return cell_value
            except ValueError:
                # Should be covered above, but safety net
                return ERROR_GENERAL

        elif isinstance(operand, BinaryOp):
            left = _resolve_operand(operand.left)
            right = _resolve_operand(operand.right)
            return _apply_binary_op(left, operand.op, right)

        elif isinstance(operand, UnaryOp):
            operand_val = _resolve_operand(operand.operand)
            return _apply_unary_op(operand.op, operand_val)

        else:
            # Should not happen
            return ERROR_GENERAL

    def _apply_unary_op(op: str, operand: Union[int, float, str, ErrorValue]) -> Union[int, float, str, ErrorValue]:
        if isinstance(operand, ErrorValue):
            return operand # Propagate error
        if isinstance(operand, str) and not operand.replace('.', '', 1).isdigit():
            return ERROR_GENERAL # Text cannot be negated/signed

        val = operand
        if op == '+':
            return val
        elif op == '-':
            if isinstance(val, int):
                return val * -1
            return float(val) * -1

        # Should not happen
        return ERROR_GENERAL

    def _apply_binary_op(left: Union[int, float, str, ErrorValue], op: str, right: Union[int, float, str, ErrorValue]) -> Union[int, float, str, ErrorValue]:

        if isinstance(left, ErrorValue) or isinstance(right, ErrorValue):
            return left if isinstance(left, ErrorValue) else right # Left error wins

        is_left_numeric = isinstance(left, (int, float))
        is_right_numeric = isinstance(right, (int, float))

        if not is_left_numeric or not is_right_numeric:
            # Rule 3: If either operand is text (non-numeric), result is #ERROR!
            return ERROR_GENERAL

        # Both are numbers
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                return ERROR_GENERAL # Division by zero
            return left / right

        return ERROR_GENERAL

    # Special handling for the root expression (when the formula itself is just one reference)
    # This requires the caller (Sheet.set) to check if the formula reduces to a single reference.
    return _resolve_operand(tree)

```

