from typing import Set, Dict, Iterable, List

class DependencyGraph:
    """
    Records and manages the dependency relationships between cells.
    All cell names must be in UPPER CASE.
    """

    def __init__(self):
        # Map: Cell Name -> Set of Precedents (cells it refers to)
        self._precedents: Dict[str, Set[str]] = {}
        # Map: Cell Name -> Set of Dependents (cells that refer to it)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replaces the cell's precedents."""

        new_precedents = set(p for p in precedents if p) # Filter out empty strings

        # 1. Update Precedents Map
        self._precedents[cell] = new_precedents

        # 2. Recalculate Dependents Map structure (simplest way is to rebuild affected parts)

        # Clear old dependencies for this cell
        if cell in self._dependents:
            for old_precedent in self._precedents.get(cell, set()):
                self._dependents[old_precedent].discard(cell)

        # Set new dependencies
        for p in new_precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Ensure the cell itself exists in the dependents structure if it has no precedents
        if cell not in self._dependents:
            self._dependents[cell] = set()


    def precedents(self, cell: str) -> Set[str]:
        """Returns the set of cells this cell directly refers to."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the set of cells that directly refer to this cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or indirectly.
        Includes 'cell' itself only if 'cell' is on a cycle.
        """

        queue = list(self.dependents.get(cell, set()))
        visited = {cell} # Start with cell itself (for cycle check)

        # BFS traversal starting from direct dependents
        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                # Add current cell's dependents to the queue
                for dependent in self.dependents.get(current, set()):
                    queue.append(dependent)

        # The set 'visited' contains everything reachable from cell's dependents.
        # We must also check if cell itself is reachable from its own precedents 
        # to determine if it should be included based on cycle logic.

        # The spec says: "It contains cell itself only when cell is on a cycle."
        # We determine the cycle set first, then refine.

        return visited

    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle.
        A cell is on a cycle if following its precedents leads back to itself.
        """

        cells = list(self._precedents.keys())
        on_cycle = set()

        for start_cell in cells:
            # Use DFS to detect cycles
            visited: Set[str] = set()
            recursion_stack: Set[str] = set()

            def dfs(u: str):
                if u in recursion_stack:
                    # Cycle detected involving u
                    on_cycle.add(u)
                    return True
                if u in visited:
                    return False

                visited.add(u)
                recursion_stack.add(u)

                for v in self._precedents.get(u, set()):
                    # Check if precedent v is also part of the cycle path
                    if dfs(v):
                        on_cycle.add(u) # If a dependency is on a cycle, u is indirectly part of it
                        return True

                recursion_stack.remove(u)
                return False

            # Run DFS starting from this cell to see if it leads back to itself
            # Note: The strict definition implies checking if a path exists from cell -> ... -> cell.

            # Simpler cycle check: path from cell back to cell
            path = []
            stack = [start_cell]
            visited_cycle_check = {start_cell}

            while stack:
                current = stack.pop()
                path.append(current)

                for next_cell in self._precedents.get(current, set()):
                    if next_cell == start_cell:
                        on_cycle.add(start_cell)
                        break

                    if next_cell not in visited_cycle_check:
                        visited_cycle_check.add(next_cell)
                        stack.append(next_cell)
                else:
                    continue
                break # Stop inner loop if cycle found for start_cell

        return on_cycle

```

### `sheet/sheet.py`

```python
from typing import Dict, Any, List, Set, Callable, Union, Tuple
from .formula import (
    parse_formula, FormulaError, ErrorValue, ERROR_GENERAL, ERROR_CYCLE,
    evaluate, references, NumberLiteral
)
from .graph import DependencyGraph

# Constants
MAX_COL = 26
MAX_ROW = 999
CELL_NAMES: List[str] = [] # Will hold sorted cell names

def _col_to_letter(i: int) -> str:
    """0 -> A, 1 -> B, ..., 25 -> Z"""
    return chr(ord('A') + i)

def _row_to_int(name: str) -> Tuple[int, int]:
    """Converts 'A1' -> (0, 1) (col_index, row_number)"""
    col_str = ""
    row_str = ""

    i = 0
    while i < len(name) and name[i].isalpha():
        col_str += name[i].upper()
        i += 1
    row_str = name[i:]

    # Validate format
    if not col_str or not row_str:
        raise ValueError(f"Invalid cell name format: {name}")

    try:
        row = int(row_str)
        if row < 1 or row > MAX_ROW:
            raise ValueError

        col_idx = 0
        for char in col_str:
            col_idx = col_idx * 26 + (ord(char) - ord('A')) + 1
        col_idx -= 1 # Convert 1-based column to 0-based index

        if col_idx >= MAX_COL:
            raise ValueError

        return col_idx, row

    except ValueError:
        raise ValueError(f"Invalid row or column value in cell name: {name}")


def _generate_cell_names():
    """Generates and sorts all valid cell names (Row-major order)."""
    global CELL_NAMES
    names = []
    for r in range(1, MAX_ROW + 1):
        for c_idx in range(MAX_COL):
            col_letter = _col_to_letter(c_idx)
            names.append(f"{col_letter}{r}")
    CELL_NAMES = names


_generate_cell_names()


class Sheet:
    """The main spreadsheet engine."""

    def __init__(self):
        # Stores the raw input string for each cell name
        self._raw_data: Dict[str, str] = {} 
        # Stores the computed value of each cell (None, int, float, str, ErrorValue)
        self._values: Dict[str, Any] = {} 
        self.dependency_graph = DependencyGraph()
        self.evaluations: int = 0

        # Initialize all cells to empty
        for name in CELL_NAMES:
            self._raw_data[name] = ""
            self._values[name] = None

    def _check_name(self, name: str):
        """Validates if a cell name is within bounds."""
        if name.upper() not in [CELL_NAMES[i] for i, name_ in enumerate(CELL_NAMES) if name_.upper() == name.upper()]:
             raise ValueError(f"Cell name '{name}' is outside the valid sheet range (A1-Z999).")


    def get(self, name: str) -> Union[int, float, str, None, ErrorValue]:
        """Returns the computed value of the cell."""
        name = name.upper()
        if name not in self._values:
             raise ValueError(f"Cell name {name} is invalid.")
        return self._values[name]

    def raw(self, name: str) -> str:
        """Returns the last input string."""
        name = name.upper()
        if name not in self._raw_data:
             raise ValueError(f"Cell name {name} is invalid.")
        return self._raw_data[name]

    def cells(self) -> List[str]:
        """Returns all non-empty cell names in row-major order."""
        return [name for name, raw_val in self._raw_data.items() if raw_val.strip() != '']


    def set(self, name: str, raw_input: str) -> List[str]:
        """
        Stores input, triggers recalculation, and returns list of affected cells in row-major order.
        """
        name = name.upper()
        self._check_name(name)

        if not isinstance(raw_input, str):
            raise TypeError("Raw input must be a string.")

        old_value = self.get(name)

        # 1. Store raw input (this is done before parsing, so formula errors can be caught)
        self._raw_data[name] = raw_input

        # 2. Determine the potential new value based on raw input
        new_computed_value: Any = None

        if raw_input.strip() == '':
            new_computed_value = None
        elif raw_input.lstrip().startswith('='):
            try:
                formula_source = raw_input.lstrip()[1:].strip()
                tree = parse_formula(formula_source)

                # Check if the formula is *only* a reference
                if len(references(tree)) == 1 and isinstance(tree, (Reference, NumberLiteral)):
                    # Optimization: If it's just a literal, treat as literal
                    if isinstance(tree, NumberLiteral):
                         new_computed_value = tree.value
                    elif isinstance(tree, Reference):
                        # Need to evaluate this single reference against current values
                        new_computed_value = evaluate(tree, self.get)
                else:
                    # Standard evaluation path
                    new_computed_value = evaluate(tree, self.get)

            except FormulaError as e:
                # If parsing fails, the sheet is unchanged. Revert raw_data and return empty list.
                print(f"Formula Error in {name}: {e}") # In a real package, this wouldn't print
                self._raw_data[name] = self._raw_data[name] # Keep old raw data effectively
                return []
        else:
            # Numeric check
            stripped_input = raw_input.strip()
            if stripped_input.startswith('-'):
                try:
                    if '.' not in stripped_input[1:]:
                        new_computed_value = int(float(stripped_input)) # Use float conversion safely
                    else:
                        new_computed_value = float(stripped_input)
                except ValueError:
                    # Not a number, treat as text
                    new_computed_value = raw_input
            elif stripped_input.replace('.', '', 1).isdigit():
                 if '.' not in stripped_input:
                    new_computed_value = int(stripped_input)
                 else:
                    new_computed_value = float(stripped_input)
            else:
                # Text
                new_computed_value = raw_input

        # 3. Update the cell's value and dependencies

        # Temporary update for dependency tracking (before cycle check)
        old_cell_value = self._values[name]
        self._values[name] = new_computed_value

        # If the value didn't change (e.g., setting the same number), we might skip recalculation,
        # but the rules imply we recalculate *after* setting, so we proceed to graph updates.

        # Determine precedents only if it was a formula
        precedents = set()
        if raw_input.lstrip().startswith('='):
            try:
                formula_source = raw_input.lstrip()[1:].strip()
                tree = parse_formula(formula_source)
                precedents = references(tree)
            except FormulaError:
                # If formula parsing failed, the value remains what it was before the set attempt, 
                # but since we already updated _values, this path is messy.
                # STICKING TO THE RULE: If parsing failed, sheet is unchanged.
                self._raw_data[name] = self._raw_data[name] # Revert raw input
                self._values[name] = old_cell_value # Revert value
                return [] 


        # Update Graph (Crucial step)
        self.dependency_graph.set_dependencies(name, precedents)

        # 4. Identify affected cells for recalculation

        # Get all cells affected by the change (including self, potentially)
        affected_set = self.dependency_graph.all_dependents(name)

        # Add self to the affected set if it wasn't naturally included due to cycles
        if name not in affected_set:
            affected_set.add(name)

        # Sort affected cells in row-major order
        affected_list = sorted([a for a in affected_set if a in CELL_NAMES], key=lambda x: CELL_NAMES.index(x))

        # 5. Recalculate values for the affected list
        recalculated_count = 0

        for cell_name in affected_list:
            if cell_name in self.dependency_graph.cycle_cells():
                # Rule 2: Cycle cells get #CYCLE! and are not evaluated.
                self._values[cell_name] = ERROR_CYCLE
                continue

            # Check if the cell is a formula cell
            if self._raw_data[cell_name].lstrip().startswith('='):

                formula_source = self._raw_data[cell_name].lstrip()[1:].strip()
                try:
                    tree = parse_formula(formula_source)

                    # Evaluate ONLY if the value is currently wrong or needs calculation
                    old_val = self._values[cell_name]

                    # Evaluation logic
                    new_val = evaluate(tree, self.get)

                    # Update value if it changed
                    if old_val != new_val:
                        self._values[cell_name] = new_val
                        recalculated_count += 1

                except FormulaError:
                    # If the formula itself is broken, it stays as an error, 
                    # or whatever state it was in before the dependency update.
                    # For simplicity adhering strictly to recalculation rules, we assume
                    # if the formula is bad, it holds the last error state or is left unchanged.
                    pass 

        self.evaluations += recalculated_count

        # Return the list of cells that *might* have changed (the affected list)
        return affected_list

