# sheet/formula.py
from typing import Union, List, Set, Any, Tuple

# --- Error Handling ---

class FormulaError(ValueError):
    """Raised for syntax or parsing errors in formulas."""
    pass

class ErrorValue(str):
    """Represents an error state in a cell value."""
    def __new__(cls, value: str):
        return super().__new__(cls, value)

# Define specific error constants
ERROR_GENERAL = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- Formula AST Nodes ---

class NumberNode:
    def __init__(self, value: Union[int, float]):
        self.value = value
    def __repr__(self):
        return f"Num({self.value})"

class ReferenceNode:
    def __init__(self, name: str):
        self.name = name
    def __repr__(self):
        return f"Ref('{self.name}')"

class UnaryOpNode:
    def __init__(self, op: str, operand: Any):
        self.op = op  # '+' or '-'
        self.operand = operand
    def __repr__(self):
        return f"UnaryOp('{self.op}', {self.operand})"

class BinaryOpNode:
    def __init__(self, op: str, left: Any, right: Any):
        self.op = op  # '+', '-', '*', '/'
        self.left = left
        self.right = right
    def __repr__(self):
        return f"BinaryOp('{self.op}', {self.left}, {self.right})"

# --- Parsing ---

def _tokenize(source: str) -> List[str]:
    """Splits formula source into meaningful tokens, handling multi-char symbols."""
    # Insert spaces around operators and parentheses to facilitate splitting, 
    # but be careful not to break up numbers or references.

    # Simplification: We will iterate character by character to handle whitespace properly.

    tokens = []
    i = 0
    n = len(source)
    while i < n:
        char = source[i]
        if char.isspace():
            i += 1
            continue

        # Operators and Parentheses
        if char in '+-*/()':
            tokens.append(char)
            i += 1
            continue

        # Numbers (digits, potentially with a decimal point)
        elif char.isdigit() or char == '.':
            j = i
            has_dot = False
            while j < n and (source[j].isdigit() or source[j] == '.'):
                if source[j] == '.':
                    if has_dot:
                        raise FormulaError("Multiple decimal points in number.")
                    has_dot = True
                j += 1
            tokens.append(source[i:j])
            i = j
            continue

        # References (letters followed by digits)
        elif char.isalpha():
            j = i
            # Consume letters (for potential negative sign handled later, but here we assume it's part of the name if it starts with a letter)
            # Per grammar: ref := letters digits
            while j < n and source[j].isalpha():
                j += 1

            # Check for digits
            k = j
            while k < n and source[k].isdigit():
                k += 1

            if k > j: # It must have digits following letters
                tokens.append(source[i:k])
                i = k
                continue
            else:
                # If it starts with letters but has no digits, it's an error unless it's a unary sign that slipped through (which shouldn't happen with this tokenization)
                raise FormulaError(f"Invalid reference format starting at index {i}")

        else:
            raise FormulaError(f"Unexpected character '{char}' at index {i}")

    return tokens


def parse_formula(source: str) -> Any:
    """
    Parses the text after '=' into an Abstract Syntax Tree (AST).
    Implements recursive descent parsing respecting precedence.
    """
    source = source.strip()
    if not source:
        raise FormulaError("Formula cannot be empty.")

    tokens = _tokenize(source)

    # We use a simple token stream approach for recursive descent
    class TokenStream:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def consume(self, expected=None):
            token = self.tokens[self.pos]
            self.pos += 1
            if expected and token != expected:
                raise FormulaError(f"Expected '{expected}' but got '{token}'")
            return token

    stream = TokenStream(tokens)

    try:
        ast = _parse_expr(stream)
        if stream.peek() is not None:
            raise FormulaError(f"Unexpected token remaining: {stream.peek()}")
        return ast
    except IndexError:
        raise FormulaError("Incomplete expression or unbalanced parentheses.")


# --- Recursive Descent Parsing Functions (Precedence Handling) ---
# Grammar precedence: unary > *, / > +, -

def _parse_unary(stream: 'TokenStream') -> Any:
    token = stream.peek()

    # Handle unary signs (+ or -)
    if token in ('+', '-'):
        op = stream.consume()
        operand = _parse_unary(stream) # Unary operator binds tightly, so we recurse
        return UnaryOpNode(op, operand)

    # Otherwise, it's a primary expression (number, ref, or parenthesized expr)
    return _parse_primary(stream)

def _parse_primary(stream: 'TokenStream') -> Any:
    token = stream.peek()

    if token == '(':
        stream.consume('(')
        expr = _parse_expr(stream)
        stream.consume(')')
        return expr

    elif token.lstrip('-').isdigit(): # Check if it starts like a number (handles potential negative sign consumed by unary_op if structure allowed it, but here we check for pure digit start)
        # Check if it's a number literal
        num_str = stream.consume()
        try:
            if '.' in num_str:
                return NumberNode(float(num_str))
            else:
                return NumberNode(int(num_str))
        except ValueError:
            raise FormulaError(f"Invalid number format: {num_str}")

    elif token.isalpha(): # Must be a reference
        ref_str = stream.consume()
        if not ref_str.isdigit() or ref_str.startswith('0') and len(ref_str) > 1:
            # Basic check for valid reference structure (letters followed by digits)
            # Full validation against sheet limits is done in references()
            pass
        return ReferenceNode(ref_str)

    else:
        raise FormulaError(f"Unexpected token in primary expression: {token}")


def _parse_term(stream: 'TokenStream') -> Any:
    # Handles *, / (left associative)
    left = _parse_unary(stream)

    while stream.peek() in ('*', '/'):
        op = stream.consume()
        right = _parse_unary(stream)
        left = BinaryOpNode(op, left, right)

    return left

def _parse_expr(stream: 'TokenStream') -> Any:
    # Handles +, - (left associative)
    left = _parse_term(stream)

    while stream.peek() in ('+', '-'):
        op = stream.consume()
        right = _parse_term(stream)
        left = BinaryOpNode(op, left, right)

    return left


# --- Reference Extraction ---

def references(tree: Any) -> Set[str]:
    """Recursively finds all cell references in the AST."""
    refs = set()

    def traverse(node):
        if isinstance(node, ReferenceNode):
            refs.add(node.name)
        elif isinstance(node, (UnaryOpNode, BinaryOpNode)):
            if isinstance(node.operand, (UnaryOpNode, BinaryOpNode)): # Unary or Binary node
                traverse(node.operand)
                if hasattr(node, 'left'):
                    traverse(node.left)
                    traverse(node.right)
            elif isinstance(node.operand, ReferenceNode):
                traverse(node.operand)
        elif isinstance(node, (NumberNode,)):
            pass # No references in numbers
        else:
            # Handle the case where the node might be the root and complex structure
            if isinstance(node, BinaryOpNode):
                traverse(node.left)
                traverse(node.right)
            elif isinstance(node, UnaryOpNode):
                 traverse(node.operand)


    # A specialized traversal might be cleaner based on the AST structure above
    def deep_search(node):
        if isinstance(node, ReferenceNode):
            refs.add(node.name)
        elif isinstance(node, UnaryOpNode):
            deep_search(node.operand)
        elif isinstance(node, BinaryOpNode):
            deep_search(node.left)
            deep_search(node.right)

    deep_search(tree)
    return refs

# --- Evaluation ---

def evaluate(tree: Any, lookup: callable) -> Union[int, float, str]:
    """
    Computes the formula value given a lookup function.
    lookup(name) returns the cell's current value (int, float, str, None, ErrorValue).
    """

    def apply_op(op: str, left_val: Any, right_val: Any) -> Union[int, float, str]:
        # Rule 3: Error propagation
        if isinstance(left_val, ErrorValue):
            return left_val
        if isinstance(right_val, ErrorValue):
            return right_val

        # Rule 3: Text propagation
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
            return ERROR_GENERAL
        if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ERROR_GENERAL

        # If we reach here, operands are numeric types (int/float) or None (treated as 0)

        l = left_val if isinstance(left_val, (int, float)) else 0
        r = right_val if isinstance(right_val, (int, float)) else 0

        if op == '+':
            return l + r
        elif op == '-':
            return l - r
        elif op == '*':
            return l * r
        elif op == '/':
            if r == 0:
                return ERROR_GENERAL
            return l / r

        raise RuntimeError("Unknown operator during evaluation")

    def resolve_value(node: Any) -> Union[int, float, str]:
        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, ReferenceNode):
            name = node.name
            cell_value = lookup(name)

            # Rule 2: Empty cell gives 0, but only if the formula is purely a reference
            if cell_value is None:
                # This function can't know if it's purely a reference, so we return 0 
                # and rely on the caller (evaluate) to check if the original tree was just a RefNode.
                return 0

            # Rule 2: Return text unchanged if it's text (not an error)
            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                return cell_value

            # If it's an error value, pass it through
            if isinstance(cell_value, ErrorValue):
                return cell_value

            # Otherwise, return the numeric value
            return cell_value

        elif isinstance(node, UnaryOpNode):
            operand_val = resolve_value(node.operand)

            if isinstance(operand_val, ErrorValue):
                return operand_val

            # Unary +/- applied to numbers
            if isinstance(operand_val, (int, float)):
                if node.op == '+':
                    return operand_val
                else: # node.op == '-'
                    return -operand_val

            # Unary +/- applied to text results in ERROR!
            return ERROR_GENERAL

        elif isinstance(node, BinaryOpNode):
            left_val = resolve_value(node.left)
            right_val = resolve_value(node.right)

            # Rule 3: Handle text/error propagation before arithmetic
            if isinstance(left_val, str) and not isinstance(left_val, ErrorValue):
                return ERROR_GENERAL
            if isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
                return ERROR_GENERAL

            # Rule 3: Error propagation
            if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
                return left_val if isinstance(left_val, ErrorValue) else right_val

            # Perform arithmetic (Rule 4)
            return apply_op(node.op, left_val, right_val)

        raise RuntimeError("Unknown AST node type during evaluation")

    # Special case: If the entire tree is a single reference node, return its raw value 
    # (which might be text or None/0 if we resolve it inside resolve_value)
    if isinstance(tree, ReferenceNode):
        return lookup(tree.name)

    # General case: evaluate the expression
    result = resolve_value(tree)

    # Final check: if the result is a number, return it. If it's a string, check if it's an error.
    if isinstance(result, (int, float)):
        return result

    return result

