# sheet/graph.py
from typing import Set, Dict, Iterable

class DependencyGraph:
    """
    Records and manages dependencies between cells based on their formulas.
    """
    def __init__(self):
        # Maps cell name -> set of cells it depends on (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # Maps cell name -> set of cells that depend on it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Sets the predecessors for a given cell.
        """
        precedent_set = set(p for p in precedents if p)
        self._precedents[cell] = precedent_set

        # Rebuild dependents structure based on new precedents for this cell
        # Clear existing dependents related to this cell
        for p in self._precedents:
            if cell in self._dependents.get(p, set()):
                self._dependents[p].remove(cell)

        # Update dependents for the new precedents
        for p_name in precedent_set:
            if p_name not in self._dependents:
                self._dependents[p_name] = set()
            self._dependents[p_name].add(cell)

        # Ensure the cell itself is in the dependents map even if it has no precedents
        if cell not in self._dependents:
            self._dependents[cell] = set()


    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells this cell depends on."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on this cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or transitively.
        Includes 'cell' itself if it is on a cycle.
        """
        if cell not in self._precedents and cell not in self._dependents:
            return set()

        # Use BFS/DFS starting from the cell to find all cells that trace back to it 
        # through the precedent graph (i.e., cells that depend on it).

        queue = [cell]
        visited = {cell}
        all_deps = {cell}

        # We traverse the dependents graph outwards
        while queue:
            current = queue.pop(0)
            for dependent in self._dependents.get(current, set()):
                if dependent not in visited:
                    visited.add(dependent)
                    all_deps.add(dependent)
                    queue.append(dependent)

        return all_deps


    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle by tracing precedents backwards.
        """

        # Perform DFS on the precedent graph to detect cycles
        visiting: Set[str] = set()  # Nodes currently in the recursion stack
        visited_safe: Set[str] = set() # Nodes completely processed without finding a cycle starting from them
        cycle_set: Set[str] = set()

        def dfs_cycle_check(cell: str) -> bool:
            """Returns True if a cycle was found involving this path."""
            visiting.add(cell)

            for precedent in self._precedents.get(cell, set()):
                if precedent in visiting:
                    # Found a back edge -> Cycle detected
                    cycle_set.add(cell)
                    cycle_set.add(precedent)
                    return True

                if precedent not in visited_safe:
                    if dfs_cycle_check(precedent):
                        # If the predecessor is part of a cycle, this cell is transitively related to it
                        # (Though technically, the definition only requires the cell itself to be reachable from the cycle)
                        if precedent in cycle_set:
                            cycle_set.add(cell)
                        return True

            visiting.remove(cell)
            visited_safe.add(cell)
            return False

        # Check every cell that has precedents (or is involved)
        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        for cell in all_cells:
            if cell not in visited_safe:
                dfs_cycle_check(cell)

        return cycle_set
