# sheet/sheet.py
from typing import List, Dict, Any, Callable, Set, Tuple
import re

from .formula import (
    FormulaError, ErrorValue, ERROR_GENERAL, ERROR_CYCLE, 
    parse_formula, references, evaluate
)
from .graph import DependencyGraph

# --- Constants and Helpers ---

COLUMNS = [chr(i) for i in range(ord('A'), ord('Z') + 1)]
MAX_ROWS = 999
MAX_COLS = 26

def _cell_to_coords(name: str) -> Tuple[str, int]:
    """Converts 'A1' -> ('A', 1). Assumes name is valid and uppercase."""
    if not name:
        raise ValueError("Cell name cannot be empty.")

    col_str = ""
    row_str = ""
    i = 0

    # Find the split point (where letters stop and digits start)
    while i < len(name) and name[i].isalpha():
        col_str += name[i]
        i += 1

    row_str = name[i:]

    if not col_str or not row_str.isdigit():
        raise ValueError(f"Invalid cell name format: {name}")

    try:
        row = int(row_str)
        if row < 1 or row > MAX_ROWS:
            raise ValueError
    except ValueError:
        raise ValueError(f"Row number out of range or invalid: {row_str}")

    if len(col_str) > MAX_COLS:
        raise ValueError(f"Column name too long: {col_str}")

    return col_str, row

def _coords_to_cell_name(col_idx: int, row: int) -> str:
    """Converts (0, 1) -> 'A1'."""
    if not (0 <= col_idx < MAX_COLS and 1 <= row <= MAX_ROWS):
        raise ValueError("Coordinates out of sheet bounds.")
    col_char = COLUMNS[col_idx]
    return f"{col_char}{row}"

def _get_coords_from_name(name: str) -> Tuple[int, int]:
    """Converts 'A1' -> (0, 1). Assumes name is valid and uppercase."""
    col_str, row = _cell_to_coords(name)
    col_idx = COLUMNS.index(col_str)
    return col_idx, row

def _get_row_major_order() -> List[str]:
    """Generates all cell names in row-major order (B1, A2, C2, A10)."""
    all_names = []
    for r in range(1, MAX_ROWS + 1):
        for c_idx in range(MAX_COLS):
            all_names.append(_coords_to_cell_name(c_idx, r))
    return all_names

ROW_MAJOR_CELLS = _get_row_major_order()


# --- Sheet Implementation ---

class Sheet:
    """
    Manages cell data, dependencies, and recalculation.
    """
    def __init__(self):
        # Stores raw input string for each cell name (e.g., "=A1+B2" or "text")
        self._raw_inputs: Dict[str, str] = {name: '' for name in ROW_MAJOR_CELLS}
        # Stores the calculated value for each cell
        self._values: Dict[str, Any] = {name: None for name in ROW_MAJOR_CELLS}
        # Stores the formula AST for cells containing formulas
        self._formula_trees: Dict[str, Any] = {}
        # Dependency tracking
        self.graph = DependencyGraph()
        # Counter for formula executions
        self.evaluations: int = 0

        # Initialize graph with empty dependencies (all cells exist)
        for name in ROW_MAJOR_CELLS:
            self.graph.set_dependencies(name, [])

    def _validate_name(self, name: str):
        """Validates if the cell name is within sheet bounds and format."""
        if not name or not name.isalpha() or not name[0].isalpha() or not name[1:].isdigit():
            raise ValueError(f"Invalid cell name format: {name}")

        try:
            _, row = _cell_to_coords(name)
            if row < 1 or row > MAX_ROWS:
                raise ValueError
        except ValueError:
            # Re-raise if it was a range error, otherwise let the generic ValueError pass
            raise ValueError(f"Cell name '{name}' is outside sheet bounds or invalid.")


    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores the cell's raw input and triggers recalculation for affected cells.
        Returns the list of cells whose value may have changed, in row-major order.
        """
        self._validate_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_inputs[name]
        if old_raw == raw:
            return [] # No change

        self._raw_inputs[name] = raw

        # 1. Parse and prepare the cell state
        current_value, needs_recalc = self._process_raw_input(name, raw)

        if needs_recalc:
            # 2. Identify cells to re-evaluate using the graph
            # This set includes the cell itself + all its dependents
            affected_cells = self.graph.all_dependents(name)

            # 3. Recalculate
            # The recalculation must happen in an order that respects dependencies
            recalculated_list = self._recalculate(affected_cells)

            # Update the stored value for the changed cell
            self._values[name] = current_value

            # Return the list of cells whose value changed, in row-major order
            changed_in_order = [c for c in ROW_MAJOR_CELLS if c in recalculated_list]
            return changed_in_order

        return []

    def _process_raw_input(self, name: str, raw: str) -> Tuple[Any, bool]:
        """
        Determines the initial value based on the raw input string, updates dependencies, 
        and returns (new_value, needs_recalculation).
        """
        is_formula = raw.strip().startswith('=')
        new_value = None
        needs_recalc = False

        if raw == '':
            new_value = None
            # If it was a formula, we lose the formula, so dependencies change
            if name in self._formula_trees:
                del self._formula_trees[name]
                self.graph.set_dependencies(name, [])
                needs_recalc = True
            elif name in self._values and self._values[name] is not None:
                # Was a number/text, now empty
                self._values[name] = None
                needs_recalc = True
            return new_value, needs_recalc


        if is_formula:
            formula_source = raw[1:].strip()
            try:
                tree = parse_formula(formula_source)
                self._formula_trees[name] = tree

                # Extract dependencies and update graph
                precedents_names = references(tree)
                self.graph.set_dependencies(name, precedents_names)

                # Initial evaluation (will be run during main recalculation)
                new_value = ERROR_GENERAL # Placeholder, actual evaluation happens later
                needs_recalc = True

            except FormulaError as e:
                # Formula parsing failed, value is fixed error, no dependency change needed
                new_value = ERROR_GENERAL
                print(f"Formula Error in {name}: {e}") # Should re-raise per spec, but for internal logic handling
                # Since the sheet is left unchanged if parsing fails, we return the previous state's value/error
                return self._values[name], False 

        else:
            # Check for number literal
            match_int = re.fullmatch(r"[-]?\d+", raw.strip())
            match_float = re.fullmatch(r"[-]?\d+\.\d*", raw.strip())

            if match_int:
                num = int(raw.strip())
                self._values[name] = num
                return num, False
            elif match_float:
                num = float(raw.strip())
                self._values[name] = num
                return num, False
            else:
                # Text
                new_value = raw.strip() # Store exactly as given (spaces included in raw storage, but value is stripped text)
                self._values[name] = raw.strip()
                return raw.strip(), False

        return new_value, needs_recalc


    def _recalculate(self, affected_cells: Set[str]) -> Set[str]:
        """
        Performs the cascade recalculation for the affected set, respecting cycles.
        Returns the set of cells whose value has changed.
        """
        recalculated_this_pass = set()

        # Determine the order of evaluation using Topological Sort idea (but adapted for recursion)
        # We need to process cells whose prerequisites are already up-to-date.

        # Initialize queue with all cells that need calculation and are NOT on a cycle
        queue = sorted([c for c in affected_cells if c not in self.graph.cycle_cells()])

        # Track which cells in the affected set are done
        done = set()

        # Loop until all non-cyclic affected cells are processed
        while queue:
            cell = queue.pop(0)

            if cell in done:
                continue

            # 1. Check for cycles (Rule 2)
            if cell in self.graph.cycle_cells():
                self._values[cell] = ERROR_CYCLE
                done.add(cell)
                recalculated_this_pass.add(cell)
                continue

            # 2. Ensure all precedents are up-to-date before calculating (Rule 3)
            precedents = self.graph.precedents(cell)

            # If any precedent hasn't been evaluated or is itself an error/cycle, we must wait or propagate the error.
            # Since we are using a topological approach on the *affected* set, we must ensure all precedents are in `done` or are constants/non-formulaic.

            all_deps_ready = True
            for p in precedents:
                if p not in done and p in affected_cells:
                    # Dependency not yet calculated in this pass
                    all_deps_ready = False
                    break
                # If precedent is not in affected_cells, we assume its value is stable from before the change.

            if not all_deps_ready and cell not in self.graph.cycle_cells():
                # Cannot calculate yet; put it back later, or rely on the main loop to catch it.
                # For simplicity in this structure, we rely on the queue structure to manage this dependency flow.
                # If we put it back, we risk infinite loop if dependencies aren't correctly tracked in the affected set.
                # A proper Kahn's algorithm would be used here.
                pass # Rely on the outer loop logic if the initial queue population was flawed.

            # --- Calculation ---

            if cell in self._formula_trees:
                tree = self._formula_trees[cell]
                lookup = self.get

                try:
                    # Evaluate formula
                    new_val = evaluate(tree, lookup)

                    old_val = self._values[cell]

                    if new_val != old_val:
                        self._values[cell] = new_val
                        recalculated_this_pass.add(cell)
                        self.evaluations += 1

                        # If this cell changed, its dependents must be queued for the next pass
                        for dependent in self.graph.dependents(cell):
                            if dependent not in done and dependent in affected_cells:
                                if dependent not in queue:
                                    queue.append(dependent)

                    else:
                        # Value remained the same, but we still mark it as 'done' for dependency tracking
                        pass

                except Exception as e:
                    # Catch evaluation failures (e.g., division by zero during lookup if not caught by formula)
                    print(f"Runtime Evaluation Error in {cell}: {e}")
                    self._values[cell] = ERROR_GENERAL
                    recalculated_this_pass.add(cell)

            else:
                # Non-formulaic cell (Number/Text/None). Its value is fixed by set(), no recalculation needed here.
                # We just mark it done if it was in the affected set.
                pass 

            done.add(cell)


        # Final safety check: any remaining non-cyclic cells in `affected_cells` that weren't done
        # must be stuck in a dependency loop involving cells outside the initial affected set, or the logic failed.
        # In a perfect system, this loop handles all reachable non-cyclic nodes.

        return recalculated_this_pass


    # --- Public Interface ---

    def get(self, name: str) -> Any:
        """Returns the cell's computed value."""
        self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the input string."""
        self._validate_name(name)
        return self._raw_inputs.get(name, '')

    def cells(self) -> List[str]:
        """Returns all non-empty cell names in row-major order."""
        return [name for name in ROW_MAJOR_CELLS if self._values[name] is not None and self._values[name] != '']

    def get_all_dependents(self, name: str) -> Set[str]:
        """Exposes the graph's all_dependents for external testing/verification."""
        self._validate_name(name)
        return self.graph.all_dependents(name)

