# resolve/versions.py

import re

class Version:
    """Represents a MAJOR.MINOR.PATCH version."""
    def __init__(self, text: str):
        if not re.fullmatch(r"\d+\.\d+\.\d+", text):
            raise ValueError(f"Invalid version format: {text}")

        parts = [int(p) for p in text.split('.')]
        if len(parts) != 3:
            # This should theoretically be caught by the regex, but good for robustness
            raise ValueError(f"Version must have three parts: {text}")

        self.major, self.minor, self.patch = parts

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if isinstance(other, Version):
            return self.major == other.major and \
                   self.minor == other.minor and \
                   self.patch == other.patch
        return NotImplemented

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return self > other or self == other

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    @property
    def major(self): return self.major
    @property
    def minor(self): return self.minor
    @property
    def patch(self): return self.patch

class Range:
    """Represents a set of version constraints."""

    # Regex to parse constraints: [operator]version
    CONSTRAINT_REGEX = re.compile(r"^\s*([<>=!~^]+)?\s*(\d+\.\d+\.\d+)\s*$")

    def __init__(self, spec: str):
        self.constraints = []
        if not spec:
            raise ValueError("Range spec cannot be empty.")

        # Split by comma, ignoring surrounding whitespace
        parts = [p.strip() for p in spec.split(',')]

        for part in parts:
            if not part:
                raise ValueError("Empty constraint found in range spec.")

            match = self.CONSTRAINT_REGEX.match(part)
            if not match:
                raise ValueError(f"Invalid constraint format: {part}")

            op_raw, version_str = match.groups()

            version = Version(version_str)

            if op_raw is None:
                # Implicitly means == if no operator, but per requirements, 
                # if it's just a version, it should probably be treated as ==
                # However, the spec description implies operators are mandatory for specific versions
                # Let's treat no operator as an error unless it's '*', which we handle separately.
                raise ValueError(f"Missing operator in constraint: {part}")

            op = op_raw

            if op == '*':
                self.constraints.append(('*', None))
                continue

            self.constraints.append((op, version))

    def contains(self, v: Version) -> bool:
        """Checks if the given Version satisfies all constraints."""
        for op, required_version in self.constraints:
            if op == '*':
                continue

            if op == "==":
                if v != required_version: return False
            elif op == "!=":
                if v == required_version: return False
            elif op == ">":
                if not v > required_version: return False
            elif op == ">=":
                if not v >= required_version: return False
            elif op == "<":
                if not v < required_version: return False
            elif op == "<=":
                if not v <= required_version: return False
            elif op == "~":
                # ~1.2.3 is >=1.2.3 and <1.3.0
                if not v >= required_version: return False

                # Calculate the next minor/patch bump for the upper bound
                major, minor, patch = required_version.major, required_version.minor, required_version.patch

                if patch < 9:
                    upper_bound = Version(f"{major}.{minor}.{patch + 1}")
                elif minor < 9:
                    upper_bound = Version(f"{major}.{minor + 1}.0")
                else: # patch=9, minor=9 (or higher, though version format limits this)
                    upper_bound = Version(f"{major + 1}.0.0")

                if v >= upper_bound: return False

            elif op == "^":
                # ^1.2.3: >=1.2.3 and <2.0.0 (if major > 0)
                # ^0.2.3: >=0.2.3 and <0.3.0
                major, minor, patch = required_version.major, required_version.minor, required_version.patch

                if major > 0:
                    # Bump major version
                    upper_bound = Version(f"{major + 1}.0.0")
                elif minor > 0:
                    # Bump minor version (major is 0)
                    upper_bound = Version(f"{major}.{minor + 1}.0")
                else: # major=0, minor=0
                    # Bump patch version (e.g., ^0.0.3 -> <0.0.4)
                    upper_bound = Version(f"{major}.{minor}.{patch + 1}")

                if not v >= required_version: return False
                if v >= upper_bound: return False
        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self):
        # Reconstruct the canonical string without whitespace
        parts = []
        for op, version in self.constraints:
            if op == '*':
                parts.append('*')
            elif op:
                parts.append(f"{op}{version}")
        return ",".join(parts)

# Helper for parsing root requirements (which are strings)
def parse_range_spec(spec: str) -> Range:
    """Public interface to Range constructor."""
    return Range(spec)
