# resolve/index.py

from typing import Dict, List, Optional, Any
from .versions import Version, Range, parse_range_spec

class PackageIndex:
    """Stores known package versions and their dependencies."""

    def __init__(self):
        # Structure: {name: {version_str: {dep_name: spec_str, ...}, ...}}
        self._data: Dict[str, Dict[str, Dict[str, str]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version '{version_str}' for {name}: {e}")

        if name not in self._data:
            self._data[name] = {}

        if version_str in self._data[name]:
            raise ValueError(f"Duplicate version {version_str} for package {name} already exists.")

        # Validate requires specs
        validated_requires = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # Test parsing to ensure spec is valid
                    parse_range_spec(spec_str)
                    validated_requires[dep_name] = spec_str
                except ValueError as e:
                    raise ValueError(f"Bad requirement spec '{spec_str}' for {dep_name} in {name}@{version_str}: {e}")

        self._data[name][version_str] = validated_requires

    def versions(self, name: str) -> List[Version]:
        """Returns known versions of name, newest first."""
        if name not in self._data:
            return []

        version_strs = list(self._data[name].keys())
        versions = [Version(v) for v in version_strs]

        # Sort descending (newest first)
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns dependencies (as Range objects) for a specific version."""
        if name not in self._data:
            raise KeyError(f"Package {name} not found in index.")

        version_str = str(version)
        if version_str not in self._data[name]:
            raise KeyError(f"Version {version_str} of {name} not found in index.")

        raw_requires = self._data[name][version_str]

        # Convert requirement strings to Range objects
        ranges = {}
        for dep_name, spec_str in raw_requires.items():
            ranges[dep_name] = parse_range_spec(spec_str)

        return ranges

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a dictionary structure."""
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires in versions_data.items():
                # Note: We rely on the caller providing valid versions/specs if using this constructor
                # to simplify the implementation, matching the internal structure.
                index.add(name, version_str, requires)
        return index
