# resolve/solver.py

from typing import Dict, List, Any, Optional, Tuple
from .index import PackageIndex
from .versions import Version, Range, parse_range_spec

class ResolutionError(Exception):
    """Raised when the dependency resolution fails."""
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

    def __str__(self):
        return self.explanation

# Type aliases for clarity
Requirements = Dict[str, str]
Selection = Dict[str, Version]
Order = List[str]
Constraints = List[Tuple[str, Range]] # (Requirer, Range)

def resolve(index: PackageIndex, requirements: Requirements) -> Selection:
    """
    Resolves a set of root requirements using a backtracking DFS approach.
    """

    # Initial setup
    root_names = sorted(requirements.keys())

    # State for DFS
    order: Order = []
    selected: Selection = {}

    # The recursive backtracking function
    def dfs(current_order: Order, current_selected: Selection) -> Optional[Selection]:

        # 1. Find the next package to resolve (first in order not yet selected)
        next_package_name = None
        for name in current_order:
            if name not in current_selected:
                next_package_name = name
                break

        # Success case: All required packages have been selected
        if next_package_name is None:
            return current_selected

        pkg_name = next_package_name

        # 2. Determine constraints for pkg_name
        constraints: Constraints = []

        # A. Root requirement constraint
        root_spec = requirements.get(pkg_name)
        if root_spec:
            try:
                root_range = parse_range_spec(root_spec)
                constraints.append(("<root>", root_range))
            except ValueError as e:
                raise ResolutionError(pkg_name, f"Cannot parse root requirement for {pkg_name}: {e}")

        # B. Constraints from already selected packages
        for selected_name, selected_version in current_selected.items():
            # Check if this selected package depends on pkg_name
            try:
                deps = index.requirements(selected_name, selected_version)
                if pkg_name in deps:
                    dep_range = deps[pkg_name]
                    requirer_str = f"{selected_name} {selected_version}"
                    constraints.append((requirer_str, dep_range))
            except KeyError:
                # Should not happen if index is consistent, but handle defensively
                pass

        # 3. Get candidates (versions, newest first)
        candidates = index.versions(pkg_name)

        if not candidates:
            # Failure: No versions exist for this package
            raise ResolutionError(pkg_name, _format_failure_explanation(
                constraints, pkg_name, index, current_selected, root_names
            ))

        # 4. Iterate through candidates (newest first)
        for candidate_v in candidates:
            candidate_str = str(candidate_v)

            # Check Constraint 1: Does candidate satisfy all ranges?
            is_acceptable = True
            for requirer, required_range in constraints:
                if not required_range.contains(candidate_v):
                    is_acceptable = False
                    break

            if not is_acceptable:
                # This version is excluded by range constraints. We need to record this
                # exclusion reason for the final error explanation, if we exhaust all options.
                # We continue iterating to see if a later candidate is acceptable.
                continue 

            # Check Constraint 2: Does candidate conflict with already selected dependencies?
            conflict_found = False
            for selected_name, selected_version in current_selected.items():
                try:
                    deps = index.requirements(selected_name, selected_version)
                    if pkg_name in deps:
                        dep_range = deps[pkg_name]

                        # Check if the currently selected version of pkg_name (candidate_v) 
                        # is within the range required by selected_name.
                        if not dep_range.contains(candidate_v):
                             # Wait, the requirement is the *other way around* in the prompt:
                             # "for every dependency of the candidate that is already selected, 
                             # the selected version is in the dependency's range."
                             # This implies: candidate_v requires 'selected_name', and 'selected_name' 
                             # must satisfy the range specified by candidate_v.

                             # Get candidate_v's requirements
                             candidate_deps = index.requirements(pkg_name, candidate_v)
                             if selected_name in candidate_deps:
                                 required_range_by_candidate = candidate_deps[selected_name]

                                 if not required_range_by_candidate.contains(selected_version):
                                     # Conflict found: candidate_v requires selected_name in range R, but selected_version is outside R.
                                     conflict_found = True
                                     break
                except KeyError:
                    pass

            if conflict_found:
                # This version conflicts with an already selected dependency.
                continue

            # If we reach here, candidate_v is acceptable. Select it and recurse.

            new_selected = current_selected.copy()
            new_selected[pkg_name] = candidate_v

            # 5. Determine new names to add to the order
            new_names_to_add = []
            candidate_deps = index.requirements(pkg_name, candidate_v)

            for dep_name in candidate_deps:
                if dep_name not in current_selected and dep_name not in current_order:
                    new_names_to_add.append(dep_name)

            new_names_to_add.sort()
            new_order = current_order + new_names_to_add

            # Recursive call
            result = dfs(new_order, new_selected)

            if result is not None:
                # Success path found! Return immediately.
                return result

        # 6. Exhausted all candidates for pkg_name without success. Failure.
        raise ResolutionError(pkg_name, _format_failure_explanation(
            constraints, pkg_name, index, current_selected, root_names
        ))

    try:
        return dfs(root_names, {})
    except ResolutionError as e:
        # Re-raise the specialized error
        raise e


def _format_failure_explanation(
    constraints: Constraints, 
    pkg_name: str, 
    index: PackageIndex, 
    current_selected: Selection, 
    root_names: List[str]
) -> str:
    """Generates the detailed error explanation string."""

    lines = [f"cannot resolve {pkg_name}"]

    # 2. Constraints listed in order
    for requirer, required_range in constraints:
        lines.append(f"  {requirer} requires {pkg_name} {str(required_range)}")

    # 3. Check versions for exclusion reasons
    versions = index.versions(pkg_name)
    if not versions:
        lines.append(f"  no versions of {pkg_name} are known")
        return "\n".join(lines)

    # For versions that exist, check why they were excluded
    for candidate_v in versions:
        candidate_str = str(candidate_v)

        # Check Range Exclusion (Constraint 1 failure)
        range_fail = False
        for requirer, required_range in constraints:
            if not required_range.contains(candidate_v):
                range_fail = True
                break

        if range_fail:
            lines.append(f"  {pkg_name} {candidate_str} is excluded by the constraints")
            continue

        # Check Dependency Conflict (Constraint 2 failure)
        # If it passed range checks, we check dependencies against selected versions
        conflict_dep = None

        candidate_deps = index.requirements(pkg_name, candidate_v)

        # Check dependencies of candidate_v against already selected packages
        for dep_name in sorted(candidate_deps.keys()):
            if dep_name in current_selected:
                selected_v = current_selected[dep_name]
                required_range = candidate_deps[dep_name]

                if not required_range.contains(selected_v):
                    conflict_dep = dep_name
                    break

        if conflict_dep:
            lines.append(f"  {pkg_name} {candidate_str} requires {conflict_dep} {str(candidate_deps[conflict_dep])}, but {conflict_dep} {str(selected_v)} is selected")

    return "\n".join(lines)
