# resolve/versions.py

import re
from typing import Tuple, Union

class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        if not re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", text):
            raise ValueError(f"Invalid version format: {text}. Must be MAJOR.MINOR.PATCH.")

        parts = tuple(int(p) for p in text.split('.'))
        self.major, self.minor, self.patch = parts
        self._tuple = parts

    @property
    def major(self) -> int:
        return self._tuple[0]

    @property
    def minor(self) -> int:
        return self._tuple[1]

    @property
    def patch(self) -> int:
        return self._tuple[2]

    def __hash__(self) -> int:
        return hash(self._tuple)

    def __eq__(self, other) -> bool:
        if isinstance(other, Version):
            return self._tuple == other._tuple
        return False

    def __lt__(self, other: 'Version') -> bool:
        return self._tuple < other._tuple

    def __le__(self, other: 'Version') -> bool:
        return self._tuple <= other._tuple

    def __gt__(self, other: 'Version') -> bool:
        return self._tuple > other._tuple

    def __ge__(self, other: 'Version') -> bool:
        return self._tuple >= other._tuple

    def __str__(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self) -> str:
        return f"Version('{str(self)}')"

class Range:
    """Represents a version constraint range."""

    # Regex to capture operator and version, handling optional whitespace
    CONSTRAINT_RE = re.compile(r"^\s*([=!<>~^]+)?\s*([\d\.]+)\s*$")

    def __init__(self, spec: str):
        self._spec = spec.strip()
        self._constraints = []
        self._parse_spec()

    def _parse_spec(self):
        if not self._spec:
            self._constraints = []
            return

        constraints = []
        parts = self._spec.split(',')

        for part in parts:
            part = part.strip()
            if not part:
                continue

            match = self.CONSTRAINT_RE.match(part)
            if not match:
                raise ValueError(f"Invalid constraint format in spec: {part}")

            op_str, version_text = match.groups()

            if op_str is None:
                op_str = "*"

            if op_str == "*":
                constraints.append(('*', None))
            else:
                try:
                    version = Version(version_text)
                    constraints.append((op_str, version))
                except ValueError:
                    raise ValueError(f"Bad version specified in constraint: {version_text}")

        self._constraints = constraints

    @property
    def spec(self) -> str:
        return ",".join([c[0] + str(c[1]) if c[1] else c[0] for c in self._constraints])

    def __str__(self) -> str:
        # Return the original spec, stripped of surrounding whitespace
        return self._spec

    def contains(self, version: Version) -> bool:
        """Checks if the version satisfies all constraints in the range."""
        for op, v_spec in self._constraints:
            if op == "*":
                continue

            v_spec_version = v_spec

            if op == "==":
                if not (version == v_spec_version):
                    return False
            elif op == "!=":
                if version == v_spec_version:
                    return False
            elif op == ">":
                if not (version > v_spec_version):
                    return False
            elif op == ">=":
                if not (version >= v_spec_version):
                    return False
            elif op == "<":
                if not (version < v_spec_version):
                    return False
            elif op == "<=":
                if not (version <= v_spec_version):
                    return False
            elif op == "^":
                if not self._check_caret(version, v_spec_version):
                    return False
            elif op == "~":
                if not self._check_tilde(version, v_spec_version):
                    return False
        return True

    def _next_major(self, v: Version) -> Version:
        return Version(f"{v.major + 1}.0.0")

    def _next_minor(self, v: Version) -> Version:
        return Version(f"{v.major}.{v.minor + 1}.0")

    def _next_patch(self, v: Version) -> Version:
        return Version(f"{v.major}.{v.minor}.{v.patch + 1}")

    def _check_caret(self, version: Version, base_v: Version) -> bool:
        # ^X.Y.Z is >=X.Y.Z and <(X+1).0.0 or <X.(Y+1).0 if X=0 and Y>0 or <X.Y.(Z+1) if X=Y=0
        if base_v.major > 0:
            # ^1.2.3 is >=1.2.3 and <2.0.0
            upper_bound = self._next_major(base_v)
        elif base_v.major == 0 and base_v.minor > 0:
            # ^0.2.3 is >=0.2.3 and <0.3.0
            upper_bound = self._next_minor(base_v)
        elif base_v.major == 0 and base_v.minor == 0:
            # ^0.0.3 is >=0.0.3 and <0.0.4
            upper_bound = self._next_patch(base_v)
        else: # ^0.0.0 is >=0.0.0 and <0.0.1
             upper_bound = self._next_patch(base_v)

        return version >= base_v and version < upper_bound

    def _check_tilde(self, version: Version, base_v: Version) -> bool:
        # ~1.2.3 is >=1.2.3 and <1.3.0
        if base_v.major == 0 and base_v.minor == 0:
            # ~0.0.3 is >=0.0.3 and <0.0.4
            upper_bound = self._next_patch(base_v)
        else:
            # ~1.2.3 is >=1.2.3 and <1.3.0
            upper_bound = self._next_minor(base_v)

        return version >= base_v and version < upper_bound

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __bool__(self) -> bool:
        # Used when checking if range is empty, though this case should be handled earlier
        return bool(self._constraints)

