# resolve/index.py

from typing import Dict, List, Optional
from .versions import Version, Range

class PackageIndex:
    """Stores package versions and their requirements."""

    def __init__(self):
        # {name: {version_str: {dep_name: range_spec, ...}}}
        self._packages: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a specific release version to the index."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version string '{version_str}': {e}")

        if name not in self._packages:
            self._packages[name] = {}

        if version_str in self._packages[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}.")

        parsed_requires: Dict[str, Range] = {}
        if requires:
            for dep_name, spec in requires.items():
                try:
                    parsed_requires[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Bad dependency spec for {name}@{version_str}: {e}")

        self._packages[name][version_str] = parsed_requires

    def versions(self, name: str) -> List[Version]:
        """Returns known versions of a package, newest first."""
        if name not in self._packages:
            return []

        version_strs = self._packages[name].keys()
        versions = [Version(v_str) for v_str in version_strs]
        # Sort descending (newest first)
        versions.sort(reverse=True)
        return versions

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns requirements for a specific version, raises KeyError if not found."""
        if name not in self._packages:
            raise KeyError(f"Package {name} not found.")

        version_str = str(version)
        if version_str not in self._packages[name]:
            raise KeyError(f"Version {version_str} of package {name} not found.")

        return self._packages[name][version_str]

    @classmethod
    def from_dict(cls, data: Dict) -> 'PackageIndex':
        """Builds an index from the specified dictionary structure."""
        index = cls()
        for name, versions_data in data.items():
            for version_str, reqs_data in versions_data.items():

                # Convert spec strings to Range objects
                parsed_reqs: Dict[str, Range] = {}
                for dep_name, spec_str in reqs_data.items():
                    try:
                        parsed_reqs[dep_name] = Range(spec_str)
                    except ValueError as e:
                        raise ValueError(f"Error parsing index data for {name}@{version_str}: {e}")

                index.add(name, version_str, requires=parsed_reqs)
        return index
