# resolve/solver.py

from typing import Dict, List, Tuple, Optional, Any
from .index import PackageIndex
from .versions import Version, Range

class ResolutionError(Exception):
    """Exception raised when package resolution fails."""
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(self.explanation)

    def __str__(self) -> str:
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves the dependencies based on the index and root requirements.
    """

    # 1. Initialization
    # Order tracks the sequence in which we MUST resolve packages
    initial_order = sorted(requirements.keys())

    # Selection tracks the successful resolution: {pkg_name: Version}
    initial_selection: Dict[str, Version] = {}

    # Start the DFS/Backtracking solver
    try:
        result_selection = _solve_recursive(
            index=index,
            requirements=requirements,
            order=initial_order,
            selection={},
            order_to_add=[],
            path_history=[],
        )
        return result_selection
    except ResolutionError as e:
        # Re-raise the captured error if it originated from the solver
        raise e
    except Exception as e:
        # Catch unexpected errors during resolution attempt
        raise ResolutionError("Internal Solver Error", f"Unexpected error during resolution: {e}")


def _solve_recursive(
    index: PackageIndex,
    requirements: Dict[str, str],
    order: List[str],  # The fixed sequence of packages to resolve
    selection: Dict[str, Version],
    order_to_add: List[str], # Names to add to 'order' during this path
    path_history: List[Tuple[str, Dict[str, Range], List[Tuple[str, str]]]] # History for error reporting
) -> Dict[str, Version]:
    """
    Backtracking solver function.
    Returns the successful selection dictionary.
    Raises ResolutionError on failure.
    """

    # Determine the next package to resolve
    current_order = order + order_to_add

    next_package_name = None
    for pkg_name in current_order:
        if pkg_name not in selection:
            next_package_name = pkg_name
            break

    # Base Case: All required packages have been selected
    if next_package_name is None:
        # Successful resolution
        return selection

    pkg_name = next_package_name

    # 2. Determine constraints for pkg_name
    constraints: List[Tuple[str, Range, str]] = [] # (requirer, range, req_spec)

    # A. Root requirement constraint
    if pkg_name in requirements:
        root_spec = requirements[pkg_name]
        try:
            root_range = Range(root_spec)
            constraints.append(("<root>", root_range, root_spec))
        except ValueError as e:
            # This should ideally be caught before calling resolve, but handle defensively
            raise ResolutionError(pkg_name, f"Root requirement spec '{root_spec}' is invalid: {e}") from e

    # B. Constraints from already selected packages
    for selected_pkg_name, selected_version in selection.items():
        if pkg_name in index.requirements(selected_pkg_name, selected_version):
            reqs = index.requirements(selected_pkg_name, selected_version)
            if pkg_name in reqs:
                req_range = reqs[pkg_name]
                # Requirer format: name version
                requirer_str = f"{selected_pkg_name} {selected_version}"
                constraints.append((requirer_str, req_range, str(req_range)))

    # 3. Get candidates (newest first)
    candidates_versions = index.versions(pkg_name)

    acceptable_candidates = []

    # 4. Filter candidates
    for candidate_version in candidates_versions:
        is_acceptable = True

        # Check Constraint 1: Does the version satisfy all range constraints?
        for _, req_range, _ in constraints:
            if not req_range.contains(candidate_version):
                is_acceptable = False
                break

        if not is_acceptable:
            continue

        # Check Constraint 2: Does it conflict with already selected dependencies?
        conflicting_dependency = None
        try:
            candidate_reqs = index.requirements(pkg_name, candidate_version)
        except KeyError:
             # Should not happen if version came from index.versions(pkg_name)
             continue 

        for dep_name in sorted(candidate_reqs.keys()):
            if dep_name in selection:
                selected_dep_version = selection[dep_name]
                dep_range = candidate_reqs[dep_name]

                if not dep_range.contains(selected_dep_version):
                    conflicting_dependency = dep_name
                    break

        if conflicting_dependency:
            is_acceptable = False

        if is_acceptable:
            acceptable_candidates.append(candidate_version)

    # 5. Attempt recursive calls (Backtracking)

    # Store current state for error reporting if resolution fails later
    current_path_history = []
    for req_name, req_range, _ in constraints:
        current_path_history.append((req_name, req_range, []))

    for candidate_version in acceptable_candidates:

        # --- Selection ---
        new_selection = selection.copy()
        new_selection[pkg_name] = candidate_version

        new_order_to_add = list(order_to_add)

        # Identify dependencies that need to be added to the order
        candidate_reqs = index.requirements(pkg_name, candidate_version)
        new_deps_to_add = []
        for dep_name in candidate_reqs:
            if dep_name not in selection and dep_name not in order:
                # Ensure we only add dependencies that haven't been placed in the queue yet
                if dep_name not in order_to_add:
                    new_deps_to_add.append(dep_name)

        # Add new dependencies to order_to_add, sorted alphabetically
        new_deps_to_add.sort()
        new_order_to_add.extend(new_deps_to_add)

        # --- Recurse ---
        try:
            result = _solve_recursive(
                index,
                requirements,
                order,
                new_selection,
                new_order_to_add,
                path_history + [
                    (pkg_name, 
                     constraints[0][1] if constraints else Range("*"), # Use root range as placeholder
                     [(req, str(r)) for req, r, _ in constraints]) # Actual constraint list
                    ]
                )
            )
            # Success found down this path
            return result
        except ResolutionError as e:
            # This candidate failed, continue to the next one (backtracking)
            if e.package == pkg_name:
                # If the error was generated specifically for this package, we continue the loop
                # The error message construction handles the failure for this candidate.
                pass 
            else:
                # Propagate errors from deeper levels
                raise e

    # 6. Failure: No candidate worked

    # Construct the failure explanation
    explanation_lines = [f"cannot resolve {pkg_name}"]

    # Constraint lines
    for req_spec, req_range, _ in constraints:
        requirer, _, _ = req_spec
        explanation_lines.append(f"  {requirer} requires {pkg_name} {req_range}")

    # Version exclusion/conflict lines
    if not candidates_versions:
        explanation_lines.append(f"  no versions of {pkg_name} are known")
    else:
        for candidate_version in candidates_versions:

            # Check if it was excluded by range constraints
            range_violated = False
            for _, req_range, _ in constraints:
                if not req_range.contains(candidate_version):
                    range_violated = True
                    break

            if range_violated:
                explanation_lines.append(f"  {pkg_name} {candidate_version} is excluded by the constraints")
                continue

            # Check for dependency conflicts
            candidate_reqs = index.requirements(pkg_name, candidate_version)
            conflict_found = False
            for dep_name in sorted(candidate_reqs.keys()):
                if dep_name in selection:
                    selected_dep_version = selection[dep_name]
                    dep_range = candidate_reqs[dep_name]

                    if not dep_range.contains(selected_dep_version):
                        # First conflicting dependency in alphabetical order
                        explanation_lines.append(f"  {pkg_name} {candidate_version} requires {dep_name} {dep_range}, but {dep_name} {selected_dep_version} is selected")
                        conflict_found = True
                        break

            if not conflict_found:
                # This candidate is acceptable regarding selection constraints, 
                # but it must have failed recursively.
                # The detailed failure reason will be propagated from the recursive call.
                # We rely on the loop structure above to handle propagation, 
                # but if we reach here, it means all recursive branches failed. 
                # For the error message, we just state it was excluded because no path worked.
                pass


    explanation = "\n".join(explanation_lines)
    raise ResolutionError(pkg_name, explanation)

